<?php
require_once __DIR__ . '/../php/layout.php';
require_once __DIR__ . '/../php/crud.php';
$user = requireProfile(['financeiro']);
$database = db(); $message = null;
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    verifyCsrf();
    try {
        $action = $_POST['action'] ?? '';
        if ($action === 'charge') {
            $amountCents = moneyToCents($_POST['valor_total'] ?? '0'); $clientId = (int) ($_POST['cliente_id'] ?? 0); $type = trim($_POST['tipo'] ?? '');
            if ($amountCents <= 0 || !$clientId || !in_array($type, ['consulta', 'retorno', 'exame', 'internacao', 'convenio'], true)) throw new InvalidArgumentException('Cliente, tipo e valor valido sao obrigatorios.');
            $client = $database->prepare('SELECT id FROM clientes WHERE id = ?'); $client->execute([$clientId]); if (!$client->fetch()) throw new InvalidArgumentException('Cliente invalido.');
            $database->prepare('INSERT INTO cobrancas (cliente_id, tipo, referencia_id, valor_total) VALUES (?, ?, ?, ?)')->execute([$clientId, $type, (int) ($_POST['referencia_id'] ?? 0), centsToMoney($amountCents)]); $message = 'Cobranca registrada.';
        } elseif ($action === 'payment') {
            $chargeId = (int) ($_POST['cobranca_id'] ?? 0); $amountCents = moneyToCents($_POST['valor'] ?? '0'); $form = trim($_POST['forma'] ?? '');
            if ($chargeId <= 0 || $amountCents <= 0 || $form === '') throw new InvalidArgumentException('Cobranca, valor e forma de pagamento sao obrigatorios.');
            $charge = $database->prepare('SELECT valor_total, valor_pago, status FROM cobrancas WHERE id = ?'); $charge->execute([$chargeId]); $charge = $charge->fetch();
            if (!$charge || $charge['status'] === 'paga') throw new InvalidArgumentException('Cobranca inexistente ou ja paga.');
            $remainingCents = moneyToCents($charge['valor_total']) - moneyToCents($charge['valor_pago']); if ($amountCents > $remainingCents) throw new InvalidArgumentException('Pagamento maior que o saldo da cobranca.');
            $amount = centsToMoney($amountCents); $database->beginTransaction(); $database->prepare('INSERT INTO pagamentos (cobranca_id, valor, forma, responsavel_id) VALUES (?, ?, ?, ?)')->execute([$chargeId, $amount, $form, $user['id']]); $database->prepare("UPDATE cobrancas SET valor_pago = valor_pago + ?, status = CASE WHEN valor_pago + ? >= valor_total THEN 'paga' ELSE 'parcial' END WHERE id = ?")->execute([$amount, $amount, $chargeId]); $database->commit(); $message = 'Pagamento registrado.';
        } elseif ($action === 'convenio') {
            $coverageText = trim($_POST['cobertura'] ?? ''); $coverage = $coverageText === '' ? -1 : moneyToCents($coverageText) / 100; if (trim($_POST['nome'] ?? '') === '' || trim($_POST['registro'] ?? '') === '' || $coverage < 0 || $coverage > 100) throw new InvalidArgumentException('Nome, registro e cobertura entre 0 e 100 sao obrigatorios.');
            $database->prepare('INSERT INTO convenios (nome, registro, cobertura) VALUES (?, ?, ?)')->execute([trim($_POST['nome']), trim($_POST['registro']), number_format($coverage, 2, '.', '')]); $message = 'Convenio cadastrado.';
        } elseif ($action === 'link_convenio') {
            $clientId = (int) ($_POST['cliente_id'] ?? 0); $convenioId = (int) ($_POST['convenio_id'] ?? 0); $number = trim($_POST['numero_convenio'] ?? ''); $start = trim($_POST['convenio_inicio'] ?? ''); $end = trim($_POST['convenio_fim'] ?? ''); $check = $database->prepare('SELECT COUNT(*) FROM convenios WHERE id = ? AND status = ?'); $check->execute([$convenioId, 'ativo']);
            if (!$clientId || !$convenioId || !(int) $check->fetchColumn()) throw new InvalidArgumentException('Cliente ou convenio invalido.');
            if ($number === '' || $start === '') throw new InvalidArgumentException('Numero e inicio da vigencia sao obrigatorios.');
            $database->prepare('UPDATE clientes SET convenio_id = ?, numero_convenio = ?, convenio_inicio = ?, convenio_fim = ? WHERE id = ?')->execute([$convenioId, $number, $start, $end ?: null, $clientId]); $message = 'Cliente vinculado ao convenio.';
        } elseif ($action === 'update_convenio') {
            $convenioId = (int) ($_POST['convenio_id'] ?? 0); $name = trim($_POST['nome'] ?? ''); $registration = trim($_POST['registro'] ?? ''); $coverageText = trim($_POST['cobertura'] ?? ''); $coverage = $coverageText === '' ? -1 : moneyToCents($coverageText) / 100; $status = $_POST['status'] ?? '';
            if (!$convenioId || $name === '' || $registration === '' || $coverage < 0 || $coverage > 100 || !in_array($status, ['ativo', 'inativo'], true)) throw new InvalidArgumentException('Dados invalidos para o convenio.');
            $database->prepare('UPDATE convenios SET nome = ?, registro = ?, cobertura = ?, status = ? WHERE id = ?')->execute([$name, $registration, number_format($coverage, 2, '.', ''), $status, $convenioId]); $message = 'Convenio atualizado.';
        }
    } catch (Throwable $exception) { if ($database->inTransaction()) $database->rollBack(); $message = 'Erro: ' . $exception->getMessage(); }
}
$clients = $database->query("SELECT c.id, c.convenio_id, u.nome FROM clientes c JOIN usuarios u ON u.id = c.usuario_id ORDER BY u.nome")->fetchAll();
$convenios = $database->query('SELECT * FROM convenios ORDER BY nome')->fetchAll();
$charges = $database->query("SELECT co.*, u.nome AS cliente FROM cobrancas co JOIN clientes c ON c.id = co.cliente_id JOIN usuarios u ON u.id = c.usuario_id ORDER BY co.id DESC")->fetchAll();
$totals = $database->query("SELECT tipo, COUNT(*) AS quantidade, COALESCE(SUM(valor_total), 0) AS total, COALESCE(SUM(valor_pago), 0) AS pago FROM cobrancas GROUP BY tipo ORDER BY tipo")->fetchAll();
pageStart('Financeiro', $user); if ($message) echo '<p role="status">' . e($message) . '</p>';
echo '<h2>Cobranças</h2><table><tr><th>Cliente</th><th>Tipo</th><th>Total</th><th>Pago</th><th>Status</th><th>Pagamento</th></tr>';
foreach ($charges as $charge) echo '<tr><td>' . e($charge['cliente']) . '</td><td>' . e($charge['tipo']) . '</td><td>' . e($charge['valor_total']) . '</td><td>' . e($charge['valor_pago']) . '</td><td>' . e($charge['status']) . '</td><td><form method="post"><input type="hidden" name="csrf" value="' . e(csrfToken()) . '"><input type="hidden" name="action" value="payment"><input type="hidden" name="cobranca_id" value="' . e($charge['id']) . '"><input name="valor" type="number" step="0.01" min="0.01" required><input name="forma" placeholder="Forma" required><button type="submit">Pagar</button></form></td></tr>';
echo '</table><h2>Totais por tipo</h2><table><tr><th>Tipo</th><th>Quantidade</th><th>Total</th><th>Pago</th></tr>'; foreach ($totals as $total) echo '<tr><td>' . e($total['tipo']) . '</td><td>' . e($total['quantidade']) . '</td><td>' . e($total['total']) . '</td><td>' . e($total['pago']) . '</td></tr>'; echo '</table><h2>Nova cobrança</h2><form method="post"><input type="hidden" name="csrf" value="' . e(csrfToken()) . '"><input type="hidden" name="action" value="charge"><label>Cliente: <select name="cliente_id" required><option value="">Selecione</option>'; foreach ($clients as $client) echo '<option value="' . e($client['id']) . '">' . e($client['nome']) . '</option>'; echo '</select></label><br>'; formField('Tipo', 'tipo'); formField('Referencia', 'referencia_id', 'number', '0', false); formField('Valor total', 'valor_total', 'number'); echo '<button type="submit">Registrar cobrança</button></form><h2>Novo convenio</h2><form method="post"><input type="hidden" name="csrf" value="' . e(csrfToken()) . '"><input type="hidden" name="action" value="convenio">'; formField('Nome', 'nome'); formField('Registro', 'registro'); formField('Cobertura percentual', 'cobertura', 'number', '0'); echo '<button type="submit">Cadastrar convenio</button></form><h2>Convenios</h2><table><tr><th>Nome</th><th>Registro</th><th>Status</th><th>Cobertura</th><th>Editar</th></tr>'; foreach ($convenios as $convenio) echo '<tr><td>' . e($convenio['nome']) . '</td><td>' . e($convenio['registro']) . '</td><td>' . e($convenio['status']) . '</td><td>' . e($convenio['cobertura']) . '%</td><td><form method="post"><input type="hidden" name="csrf" value="' . e(csrfToken()) . '"><input type="hidden" name="action" value="update_convenio"><input type="hidden" name="convenio_id" value="' . e($convenio['id']) . '"><input name="nome" value="' . e($convenio['nome']) . '" required><input name="registro" value="' . e($convenio['registro']) . '" required><input name="cobertura" value="' . e($convenio['cobertura']) . '" required><select name="status"><option value="ativo"' . ($convenio['status'] === 'ativo' ? ' selected' : '') . '>ativo</option><option value="inativo"' . ($convenio['status'] === 'inativo' ? ' selected' : '') . '>inativo</option></select><button type="submit">Salvar</button></form></td></tr>'; echo '</table><h2>Vincular conveniado</h2><form method="post"><input type="hidden" name="csrf" value="' . e(csrfToken()) . '"><input type="hidden" name="action" value="link_convenio"><label>Cliente: <select name="cliente_id" required>'; foreach ($clients as $client) echo '<option value="' . e($client['id']) . '">' . e($client['nome']) . '</option>'; echo '</select></label><br><label>Convenio: <select name="convenio_id" required>'; foreach ($convenios as $convenio) echo '<option value="' . e($convenio['id']) . '">' . e($convenio['nome']) . '</option>'; echo '</select></label><br>'; formField('Numero do convenio', 'numero_convenio'); formField('Inicio da vigencia', 'convenio_inicio', 'date'); formField('Fim da vigencia', 'convenio_fim', 'date', '', false); echo '<button type="submit">Vincular</button></form>'; pageEnd();
